parameters.jsCode:
const item = $input.first();
const body = item.json.body ?? item.json;
const chat = body.chat ?? {};
const ceo = body.commonEventObject ?? {};

const payload =
  chat.appCommandPayload ??
  chat.messagePayload ??
  chat.cardClickPayload ??
  chat.appActionPayload ??
  null;

const message = payload?.message ?? chat.message ?? null;
const space = payload?.space ?? message?.space ?? {};
const user = chat.user ?? payload?.user ?? body.user_context ?? {};

const annotations = message?.annotations ?? [];
const slashAnn = annotations.find(a => a.type === 'SLASH_COMMAND');

const normalized = {
  // Contexte
  hostApp: ceo.hostApp ?? 'CHAT',
  platform: ceo.platform ?? 'WEB',
  userLocale: ceo.userLocale ?? 'fr',
  eventTime: chat.eventTime ?? new Date().toISOString(),

  // Dialog
  isDialogEvent: !!payload?.isDialogEvent,
  dialogEventType: payload?.dialogEventType ?? null, // REQUEST_DIALOG, SUBMIT_DIALOG
  invokedFunction: payload?.common?.invokedFunction ?? payload?.invokedFunction ?? null,

  // Typage de l’event
  eventType: payload?.appCommandMetadata ? 'SLASH_COMMAND'
           : payload?.action ? 'CARD_CLICKED'
           : message ? 'MESSAGE'
           : 'UNKNOWN',

  // Slash command
  commandId: payload?.appCommandMetadata?.appCommandId ?? null,
  commandName: slashAnn?.slashCommand?.commandName ?? null,

  // Texte
  messageText: (message?.argumentText ?? message?.text ?? '').trim(),
  messageTextFull: message?.text ?? '',

  // Espace / thread / user
  threadName: message?.thread?.name ?? null,
  spaceName: space?.name ?? null,
  spaceType: space?.type ?? null,
  isDM: space?.type === 'DM' || space?.singleUserBotDm === true,

  userName: user?.displayName ?? 'Utilisateur',
  userEmail: user?.email ?? null,
  userId: user?.name ?? user?.email ?? null,

  // Analytics simples
  detectedLanguage: /[à-ÿ]/i.test(message?.text ?? '') ? 'fr' : 'en',
  wordCount: (message?.text ?? '').trim().split(/\s+/).filter(Boolean).length,

  _raw: { body, payload, message, space, user }
};

return [{ json: normalized }];

